-- SafetyTraining v20.038
-- Dirigente 12h: didactic v2 aligned to ASR 17/04/2025, preserving course version 1.
-- Eight managerial Learning Units grouped into the four official content areas.
-- 4x180-minute allocation is internal didactic design, not a statutory per-module duration.
-- Test Builder/question-bank configuration intentionally unchanged.

do $do$
declare
  r record;
  v_lu_id uuid;
  v_course_id uuid;
  v_course_version_id uuid;
  v_module_id uuid;
begin
  for r in select * from (values
    ('dirigente:ruolo-responsabilita-delega','DIR01 · Ruolo, obblighi, responsabilità e delega',90,'Collocare il dirigente nel sistema aziendale della prevenzione e distinguere ruolo, obblighi, responsabilità e delega di funzioni.',jsonb_build_object('didactic_version','dirigente-v2','code','DIR01','minutes',90,'slide_title','Dirigere significa organizzare decisioni che producono sicurezza','summary','Il dirigente attua le direttive del datore di lavoro organizzando l’attività e vigilando sul sistema affidato alla propria funzione. La formazione deve collegare responsabilità e poteri reali, evitando sia il formalismo sia l’idea che tutto possa essere trasferito con una delega.','detail','L’unità affronta sistema legislativo, figure della prevenzione, responsabilità civili e penali, delega di funzioni e confini decisionali. Il focus è capire quali decisioni organizzative ricadono nel perimetro del dirigente e quali richiedono escalation al datore di lavoro.','question','Quali condizioni devono essere presenti perché una responsabilità organizzativa sia realmente governabile e non solo formalmente attribuita?','case','Un dirigente riceve obiettivi produttivi e un budget, ma non può modificare turni, fermare una lavorazione critica o autorizzare una spesa urgente di sicurezza. È coerente pretendere da lui gli stessi risultati organizzativi di chi dispone dei relativi poteri?','teacher_expansion',jsonb_build_array('[0–15 min] Mappa dei poteri reali: cosa può decidere il dirigente?','[15–35 min] Ruolo, obblighi e rapporto con datore, preposti e funzioni di supporto.','[35–55 min] Responsabilità civile e penale: collegarle alle decisioni, non a formule astratte.','[55–75 min] Delega di funzioni: cosa trasferisce e cosa non risolve automaticamente.','[75–90 min] Caso budget/poteri: ricostruire decisioni, limiti ed escalation.'),'common_errors',jsonb_build_array('Confondere la qualifica contrattuale con il ruolo prevenzionistico concreto.','Pensare che la delega elimini ogni presidio organizzativo.','Attribuire responsabilità senza poteri, risorse o informazioni coerenti.'),'operational',jsonb_build_object('objective','Allineare responsabilità, poteri, risorse e flussi decisionali.','step_by_step',jsonb_build_array('Identifica il perimetro affidato','Verifica poteri e risorse','Definisci ciò che puoi decidere','Stabilisci escalation','Documenta le decisioni rilevanti'),'stop_conditions',jsonb_build_array('Responsabilità senza poteri adeguati','Decisione critica fuori dal proprio perimetro','Risorsa essenziale non disponibile')),'idea_images',jsonb_build_array(jsonb_build_object('file','organigramma-sicurezza.svg','caption','Ruoli, relazioni e linee decisionali nel sistema di prevenzione.'),jsonb_build_object('file','idea-safety-system.svg','caption','Il dirigente come nodo organizzativo tra direttive e lavoro reale.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',false,'final_assessment',false,'managerial',true))),
    ('dirigente:sistema-istituzionale-231-tutele','DIR02 · Sistema istituzionale, 231 e tutele organizzative',90,'Conoscere il sistema istituzionale della prevenzione, le procedure ispettive e le principali ricadute organizzative previste dal programma del dirigente.',jsonb_build_object('didactic_version','dirigente-v2','code','DIR02','minutes',90,'slide_title','Il dirigente dentro un sistema che viene controllato, non solo documentato','summary','Il sistema di prevenzione aziendale si confronta con organi di vigilanza, responsabilità amministrativa d’impresa e obblighi organizzativi che riguardano anche inclusione, violenza e molestie sul lavoro.','detail','L’unità presenta ASL, INL, VVF e INAIL, logica delle procedure ispettive, responsabilità amministrativa ex d.lgs. 231/2001 nel settore privato, prevenzione di violenza e molestie e inserimento dei lavoratori disabili. Il taglio resta manageriale: quali processi devono essere governati e quali evidenze devono esistere.','question','Quali elementi organizzativi rendono credibile un sistema di prevenzione davanti a un controllo esterno?','case','Durante un’ispezione emerge che procedure e organigrammi sono formalmente aggiornati, ma i responsabili di reparto descrivono prassi diverse e non sanno chi prende in carico le anomalie. Qual è la criticità principale?','teacher_expansion',jsonb_build_array('[0–15 min] Chi fa cosa: ASL, INL, VVF, INAIL.','[15–35 min] Dalla prescrizione formale all’effettività organizzativa.','[35–50 min] D.lgs. 231/2001 e collegamento con modelli organizzativi.','[50–70 min] Violenza, molestie e inclusione: non temi separati, ma aspetti organizzativi da governare.','[70–90 min] Caso ispezione: documenti coerenti con prassi e responsabilità reali.'),'common_errors',jsonb_build_array('Preparare documenti solo in vista dei controlli.','Confondere conformità formale con attuazione effettiva.','Trattare inclusione, molestie e organizzazione come temi estranei alla sicurezza.'),'operational',jsonb_build_object('objective','Rendere coerenti assetto formale, processi reali ed evidenze.','step_by_step',jsonb_build_array('Mappa obblighi e controlli','Verifica processi reali','Raccogli evidenze','Correggi incoerenze','Riesamina periodicamente'),'stop_conditions',jsonb_build_array('Documenti e prassi divergenti','Responsabilità non definite','Segnalazioni sensibili senza canale di gestione')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-inspection-flow.svg','caption','Dal controllo al miglioramento: evidenze, rilievi, azioni e verifica.'),jsonb_build_object('file','idea-sanctions-logic.svg','caption','Responsabilità e conseguenze devono essere collegate a ruoli e decisioni reali.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',false,'final_assessment',false,'managerial',true))),
    ('dirigente:processi-mog-sgsl','DIR03 · Processi di sicurezza, MOG e sistemi di gestione',90,'Organizzare processi di salute e sicurezza e comprendere la funzione dei modelli organizzativi e dei sistemi di gestione.',jsonb_build_object('didactic_version','dirigente-v2','code','DIR03','minutes',90,'slide_title','La sicurezza come processo: responsabilità, input, decisione, verifica','summary','La prevenzione funziona quando entra nei processi ordinari: acquisti, manutenzioni, turni, appalti, cambiamenti, formazione, emergenze e riesame. Il dirigente deve saper riconoscere dove il processo perde controllo.','detail','L’unità traduce l’art. 30 e i sistemi di gestione in strumenti operativi: ruoli, flussi, controlli, indicatori, audit, azioni correttive e riesame. Non si insegna un sistema certificativo specifico, ma la logica organizzativa comune.','question','Dove si rompe più facilmente un processo di sicurezza: nella regola, nell’assegnazione della responsabilità, nell’esecuzione o nella verifica?','case','Un’azienda ha una procedura di manutenzione corretta, ma nessuno verifica la chiusura delle anomalie segnalate. Il problema è tecnico o di processo?','teacher_expansion',jsonb_build_array('[0–15 min] Disegna un processo reale dall’input alla verifica.','[15–35 min] Ruoli, responsabilità, controlli e indicatori.','[35–55 min] MOG art. 30 e sistemi di gestione: cosa aggiungono alla sola procedura.','[55–75 min] Caso manutenzione: processo senza chiusura.','[75–90 min] Esercizio: trasformare un obbligo in processo con owner, scadenza, evidenza e riesame.'),'common_errors',jsonb_build_array('Pensare che il sistema di gestione coincida con la documentazione.','Non assegnare un owner al processo.','Misurare solo attività svolte e non risultati o criticità.'),'operational',jsonb_build_object('objective','Progettare processi controllabili e verificabili.','step_by_step',jsonb_build_array('Definisci input e obiettivo','Assegna owner e risorse','Stabilisci controlli','Raccogli indicatori','Gestisci deviazioni','Riesamina'),'stop_conditions',jsonb_build_array('Nessun responsabile del processo','Controllo senza criterio di accettazione','Azioni correttive senza verifica di efficacia')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-safety-system.svg','caption','La sicurezza come sistema di processi collegati.'),jsonb_build_object('file','procedura-operativa-5-fasi.svg','caption','Pianificare, eseguire, controllare e correggere.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',false,'final_assessment',false,'managerial',true))),
    ('dirigente:dvr-misure-risorse','DIR04 · Dal DVR alle decisioni: misure, risorse e sorveglianza sanitaria',90,'Tradurre la valutazione dei rischi e le direttive del datore di lavoro in priorità, risorse, misure e controlli organizzativi.',jsonb_build_object('didactic_version','dirigente-v2','code','DIR04','minutes',90,'slide_title','Il DVR non decide da solo: il dirigente deve trasformarlo in organizzazione','summary','Il dirigente deve leggere rischi e misure nel proprio contesto, assicurare risorse, tempi e responsabilità e verificare che le misure tecniche, organizzative e procedurali siano realmente attuate.','detail','Si lavora sul passaggio DVR → priorità → piano operativo → risorsa → responsabile → controllo. È inclusa l’importanza della sorveglianza sanitaria, senza invadere le competenze del medico competente.','question','Quando una misura indicata nel DVR può considerarsi realmente attuata?','case','Il DVR prevede una modifica tecnica entro tre mesi. Il budget è stato rinviato e nel frattempo si continua con una misura provvisoria non formalizzata. Quali decisioni manageriali servono subito?','teacher_expansion',jsonb_build_array('[0–15 min] Dal rischio alla decisione: leggere una misura e chiedere chi, quando, con quali risorse.','[15–35 min] Misure tecniche, organizzative e procedurali nel contesto del dirigente.','[35–50 min] Priorità e misure temporanee: condizioni, durata, responsabilità.','[50–65 min] Sorveglianza sanitaria: informazioni e flussi organizzativi.','[65–90 min] Caso budget rinviato: costruire una decisione documentata e riesaminabile.'),'common_errors',jsonb_build_array('Confondere previsione documentale con attuazione.','Usare misure provvisorie senza scadenza e verifica.','Trattare la sorveglianza sanitaria come adempimento isolato dal processo.'),'operational',jsonb_build_object('objective','Convertire misure previste in azioni assegnate, finanziate e verificate.','step_by_step',jsonb_build_array('Leggi il rischio e la misura','Definisci priorità','Assegna risorsa e responsabile','Gestisci eventuale misura temporanea','Controlla attuazione','Riesamina efficacia'),'stop_conditions',jsonb_build_array('Rischio significativo senza misura praticabile','Misura temporanea scaduta o non verificata','Indicazione sanitaria/organizzativa non presa in carico')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-dvr-reading.svg','caption','Dal DVR al piano operativo del dirigente.'),jsonb_build_object('file','modello-farfalla-rischio.svg','caption','Barriere e misure: verificare che esistano e funzionino.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',false,'final_assessment',false,'managerial',true))),
    ('dirigente:appalti-interferenze','DIR05 · Appalti, somministrazione, subappalti e rischio interferenziale',90,'Gestire le ricadute organizzative di appalti, contratti d’opera, somministrazione e subappalti, con particolare attenzione alle interferenze.',jsonb_build_object('didactic_version','dirigente-v2','code','DIR05','minutes',90,'slide_title','Quando entrano altri soggetti, cambia il sistema di rischio','summary','Un appalto non è sicuro perché esiste un contratto o un DUVRI: il dirigente deve presidiare coordinamento, informazioni, sequenze, accessi, responsabilità e cambiamenti che generano interferenze.','detail','L’unità affronta obblighi connessi ad appalti, opera, somministrazione e subappalti e la gestione del rischio interferenziale. Il DUVRI viene trattato come strumento di coordinamento, non come documento da archiviare.','question','Quali interferenze nascono da tempi, spazi, energia, viabilità o accessi condivisi anche se le lavorazioni sono tecnicamente diverse?','case','Un’impresa esterna anticipa di un giorno la manutenzione e occupa un’area che l’azienda aveva pianificato per la movimentazione interna. Il DUVRI esiste ma non contempla la sovrapposizione. Come deve reagire il dirigente?','teacher_expansion',jsonb_build_array('[0–15 min] Mappa delle interferenze: spazio, tempo, energia, accessi, viabilità, emergenze.','[15–35 min] Obblighi e flussi informativi negli appalti.','[35–55 min] DUVRI come processo vivo di coordinamento.','[55–75 min] Caso manutenzione anticipata: aggiornare il coordinamento prima della ripresa.','[75–90 min] Esercizio: chi deve sapere cosa, prima di iniziare?'),'common_errors',jsonb_build_array('Considerare il DUVRI sufficiente senza coordinamento reale.','Non aggiornare il piano quando cambiano tempi o sovrapposizioni.','Lasciare al solo preposto un problema nato da una decisione organizzativa.'),'operational',jsonb_build_object('objective','Governare interferenze e variazioni prima che entrino nel lavoro.','step_by_step',jsonb_build_array('Identifica soggetti e attività','Mappa interferenze','Coordina misure e sequenze','Comunica variazioni','Autorizza avvio/ripresa','Verifica sul campo'),'stop_conditions',jsonb_build_array('Interferenza non valutata','Sovrapposizione non coordinata','Responsabilità di area non definita')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-duvri.svg','caption','Interferenze e coordinamento tra attività diverse.'),jsonb_build_object('file','idea-safety-system.svg','caption','Più soggetti richiedono più chiarezza nei flussi decisionali.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',false,'final_assessment',false,'managerial',true))),
    ('dirigente:emergenze-organizzazione','DIR06 · Organizzare prevenzione incendi, primo soccorso ed emergenze',90,'Organizzare il sistema aziendale di risposta alle emergenze assicurando ruoli, risorse, coperture, comunicazioni e verifiche.',jsonb_build_object('didactic_version','dirigente-v2','code','DIR06','minutes',90,'slide_title','L’emergenza si gestisce prima che accada','summary','Il dirigente deve assicurare che l’organizzazione dell’emergenza sia compatibile con turni, presenze, layout, attività e cambiamenti reali. Nominare addetti non basta se il sistema non regge quando serve.','detail','L’unità tratta organizzazione di prevenzione incendi, primo soccorso e gestione emergenze dal punto di vista manageriale: coperture, sostituzioni, dotazioni, accessi, comunicazioni, esercitazioni, gestione di visitatori e imprese esterne.','question','Quali condizioni organizzative possono rendere inefficace un piano di emergenza formalmente corretto?','case','Nel turno serale sono presenti pochi addetti formati, una via di esodo è temporaneamente modificata e sono presenti manutentori esterni. Il piano generale è invariato. Il sistema è ancora adeguato?','teacher_expansion',jsonb_build_array('[0–15 min] Emergenza come sistema di capacità, non come fascicolo.','[15–35 min] Coperture, ruoli, sostituzioni e comunicazioni.','[35–55 min] Cambiamenti di layout, turni, ditte esterne e visitatori.','[55–75 min] Caso turno serale: verificare capacità reale di risposta.','[75–90 min] Checklist manageriale: cosa deve essere vero prima di considerare pronto il sistema.'),'common_errors',jsonb_build_array('Contare solo il numero nominale degli addetti.','Non riesaminare il piano dopo cambiamenti temporanei.','Separare emergenze e appalti quando gli esterni sono presenti nello stesso sito.'),'operational',jsonb_build_object('objective','Garantire una capacità di risposta coerente con il contesto reale.','step_by_step',jsonb_build_array('Verifica scenario e presenze','Controlla coperture e dotazioni','Comunica ruoli e vie','Gestisci variazioni','Esercita','Correggi'),'stop_conditions',jsonb_build_array('Copertura addetti insufficiente','Via di esodo non gestita','Ruoli di emergenza non comunicati','Variazione significativa non riesaminata')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-emergency-steps.svg','caption','Preparare la risposta prima dell’evento.'),jsonb_build_object('file','idea-evac-public.svg','caption','Esodo, persone e comunicazioni devono restare coerenti con il contesto.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',false,'final_assessment',false,'managerial',true))),
    ('dirigente:comunicazione-formazione-consultazione','DIR07 · Comunicazione, formazione, gruppi e consultazione',90,'Gestire comunicazione e informazione, obblighi formativi, gruppi di lavoro, conflitti e partecipazione dell’RLS.',jsonb_build_object('didactic_version','dirigente-v2','code','DIR07','minutes',90,'slide_title','Una decisione di sicurezza che non arriva alle persone non è ancora attuata','summary','Il dirigente deve governare il flusso tra decisione, comunicazione, formazione e verifica della comprensione, assicurando anche consultazione e partecipazione dei rappresentanti dei lavoratori.','detail','Si lavora su tecniche e strumenti di comunicazione e informazione, obblighi formativi delle diverse figure, gestione dei gruppi e dei conflitti, consultazione e partecipazione dell’RLS. Il focus è la qualità organizzativa del messaggio: destinatario, contenuto, canale, conferma, comportamento atteso.','question','Come distingui una comunicazione inviata da una comunicazione realmente recepita e tradotta in comportamento?','case','Una nuova procedura viene inviata via e-mail a tutti. Dopo una settimana due reparti continuano a lavorare come prima e i preposti danno interpretazioni diverse. Dove ha fallito il processo?','teacher_expansion',jsonb_build_array('[0–15 min] Comunicazione inviata vs comunicazione efficace.','[15–35 min] Informazione, formazione e addestramento: cosa deve governare il dirigente.','[35–55 min] Gruppi e conflitti: quando la pressione organizzativa produce scorciatoie.','[55–70 min] Consultazione RLS e partecipazione.','[70–90 min] Caso nuova procedura: ricostruire il piano di implementazione.'),'common_errors',jsonb_build_array('Considerare l’e-mail prova sufficiente di comprensione.','Formare senza verificare trasferimento sul lavoro.','Coinvolgere RLS solo a decisioni già chiuse quando è prevista partecipazione/consultazione.'),'operational',jsonb_build_object('objective','Portare una decisione organizzativa fino a comprensione, attuazione e feedback.','step_by_step',jsonb_build_array('Definisci destinatari','Scegli il canale','Comunica il comportamento atteso','Forma dove necessario','Verifica comprensione','Osserva applicazione','Raccogli feedback'),'stop_conditions',jsonb_build_array('Messaggio critico non compreso','Formazione necessaria non completata','Conflitto organizzativo che induce deviazioni')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-safety-system.svg','caption','Comunicazione e partecipazione come parti del sistema.'),jsonb_build_object('file','idea-rls-consult.svg','caption','Consultazione e partecipazione non sono passaggi decorativi.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',false,'final_assessment',false,'managerial',true))),
    ('dirigente:scenario-manageriale','DIR08 · Scenario manageriale integrato e riesame',90,'Integrare responsabilità, risorse, processi, appalti, emergenze e comunicazione in decisioni manageriali motivate.',jsonb_build_object('didactic_version','dirigente-v2','code','DIR08','minutes',90,'slide_title','Sei il dirigente: quale decisione cambia davvero il sistema?','summary','L’ultima unità mette il dirigente davanti a più segnali contemporanei e richiede di stabilire priorità, misure immediate, decisioni organizzative, responsabilità, risorse e criteri di verifica.','detail','Lo scenario deve essere adattato all’azienda. Ogni gruppo produce una mini decision record: fatti, rischi, misura immediata, decisione di medio termine, responsabile, risorsa, scadenza, evidenza attesa e criterio di riesame.','question','Qual è la differenza tra risolvere l’episodio e correggere il sistema che lo ha generato?','case','In una settimana si verificano due near miss, un appaltatore segnala un’interferenza non prevista, un reparto rinvia una formazione obbligatoria per carenza di personale e un controllo interno rileva tre azioni correttive scadute. La produzione chiede di non modificare il piano del mese. Quali sono le prime decisioni del dirigente?','teacher_expansion',jsonb_build_array('[0–10 min] Metodo: fatti → priorità → misura immediata → decisione organizzativa → owner → verifica.','[10–30 min] Scenario 1: near miss ripetuti e cause sistemiche.','[30–50 min] Scenario 2: appalto/interferenza e responsabilità di coordinamento.','[50–70 min] Scenario 3: formazione rinviata e risorse insufficienti.','[70–85 min] Scenario integrato: decision record di gruppo.','[85–90 min] Chiusura: cinque indicatori che il dirigente deve riesaminare periodicamente.'),'common_errors',jsonb_build_array('Risolvere solo l’urgenza senza eliminare la causa organizzativa.','Accettare scadenze indefinite per azioni correttive.','Non collegare priorità di sicurezza a risorse e responsabilità.'),'operational',jsonb_build_object('objective','Prendere decisioni manageriali tracciabili, assegnate e verificabili.','step_by_step',jsonb_build_array('Raccogli fatti','Stabilisci priorità','Proteggi nell’immediato','Decidi modifica organizzativa','Assegna owner e risorsa','Fissa scadenza','Definisci evidenza','Riesamina'),'stop_conditions',jsonb_build_array('Near miss ripetuto con causa aperta','Interferenza non governata','Obbligo formativo rinviato senza misura di controllo','Azione critica scaduta senza escalation')),'idea_images',jsonb_build_array(jsonb_build_object('file','modello-farfalla-rischio.svg','caption','Dall’evento alle cause e alle barriere organizzative.'),jsonb_build_object('file','idea-risk-cycle.svg','caption','Rischio, decisione, misura, verifica e riesame.'),jsonb_build_object('file','piramide-pericoli.svg','caption','Anomalie e near miss come indicatori per le decisioni manageriali.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',false,'final_assessment',false,'managerial',true,'scenario_based',true)))
  ) x(stable_key,title,minutes,summary,content)
  loop
    insert into public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    values(r.stable_key,r.title,r.summary,r.minutes,'dirigente',array['dirigente','asr-2025','managerial','role-specific'],true,jsonb_build_object('didactic_version','dirigente-v2','competency_level','dirigente','regulatory_basis','Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR'))
    on conflict (stable_key) do update set title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=public.learning_units.metadata||excluded.metadata,updated_at=now()
    returning id into v_lu_id;
    insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at)
    values(v_lu_id,1,'published',r.content,now())
    on conflict (learning_unit_id,version_number) do update set status='published',content=excluded.content,published_at=coalesce(public.learning_unit_versions.published_at,now());
  end loop;

  select id into v_course_id from public.courses where stable_key='dirigente';
  if v_course_id is not null then
    update public.courses set metadata=metadata||jsonb_build_object('didactic_preview_version','dirigente-v2','didactic_macro_blocks',4,'didactic_atomic_units',8,'didactic_focus','organization_management_decision_and_review','final_test_builder_paused',true,'delivery_constraint','classroom_vcs_or_elearning','classroom_allowed',true,'vcs_allowed',true,'elearning_asynchronous_allowed',true,'attendance_min_pct',90,'final_verification','test_or_interview','test_min_questions',30,'test_min_options',3,'test_passing_score_pct',70),updated_at=now() where id=v_course_id;

    insert into public.course_versions(course_id,version_number,status,syllabus_snapshot,normative_snapshot)
    values(v_course_id,2,'draft',jsonb_build_object('didactic_version','dirigente-v2','macro_blocks',jsonb_build_array(jsonb_build_object('key','dir-a','title','Giuridico-normativo: ruolo, responsabilità e sistema istituzionale','minutes',180),jsonb_build_object('key','dir-b','title','Gestione e organizzazione della sicurezza','minutes',180),jsonb_build_object('key','dir-c','title','Compiti specifici: rischi, appalti ed emergenze','minutes',180),jsonb_build_object('key','dir-d','title','Comunicazione, formazione, consultazione e decisioni','minutes',180)),'atomic_learning_units',8,'total_minutes',720,'internal_didactic_allocation',true,'statutory_per_module_duration',false,'purpose','managerial_decision_and_organization','final_assessment_in_scope',false),jsonb_build_object('basis','Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR; art. 18 e 37 d.lgs. 81/2008','minimum_minutes',720,'attendance_min_pct',90,'delivery',jsonb_build_object('classroom',true,'vcs',true,'elearning_asynchronous',true),'verification',jsonb_build_object('mode','test_or_interview','test_min_questions',30,'test_min_options',3,'passing_score_pct',70),'construction_addon',jsonb_build_object('required_when','dirigente_impresa_affidataria_art_97','minimum_minutes',360)))
    on conflict (course_id,version_number) do update set status='draft',syllabus_snapshot=excluded.syllabus_snapshot,normative_snapshot=excluded.normative_snapshot
    returning id into v_course_version_id;

    delete from public.course_module_units where module_id in (select id from public.course_modules where course_version_id=v_course_version_id);
    delete from public.course_modules where course_version_id=v_course_version_id;

    insert into public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_course_version_id,'dir-a','DIR-A · Giuridico-normativo: ruolo, responsabilità e sistema istituzionale',0,180) returning id into v_module_id;
    insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    select v_module_id,luv.id,x.pos,true,0,true,jsonb_build_object('didactic_version','dirigente-v2','delivery','classroom_vcs_or_elearning') from (values ('dirigente:ruolo-responsabilita-delega',1),('dirigente:sistema-istituzionale-231-tutele',2)) x(key,pos) join public.learning_units lu on lu.stable_key=x.key join public.learning_unit_versions luv on luv.learning_unit_id=lu.id and luv.version_number=1;

    insert into public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_course_version_id,'dir-b','DIR-B · Gestione e organizzazione della sicurezza',180,180) returning id into v_module_id;
    insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    select v_module_id,luv.id,x.pos,true,0,true,jsonb_build_object('didactic_version','dirigente-v2','delivery','classroom_vcs_or_elearning') from (values ('dirigente:processi-mog-sgsl',1),('dirigente:dvr-misure-risorse',2)) x(key,pos) join public.learning_units lu on lu.stable_key=x.key join public.learning_unit_versions luv on luv.learning_unit_id=lu.id and luv.version_number=1;

    insert into public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_course_version_id,'dir-c','DIR-C · Compiti specifici: rischi, appalti ed emergenze',360,180) returning id into v_module_id;
    insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    select v_module_id,luv.id,x.pos,true,0,true,jsonb_build_object('didactic_version','dirigente-v2','delivery','classroom_vcs_or_elearning') from (values ('dirigente:appalti-interferenze',1),('dirigente:emergenze-organizzazione',2)) x(key,pos) join public.learning_units lu on lu.stable_key=x.key join public.learning_unit_versions luv on luv.learning_unit_id=lu.id and luv.version_number=1;

    insert into public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_course_version_id,'dir-d','DIR-D · Comunicazione, formazione, consultazione e decisioni',540,180) returning id into v_module_id;
    insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    select v_module_id,luv.id,x.pos,true,0,true,jsonb_build_object('didactic_version','dirigente-v2','delivery','classroom_vcs_or_elearning') from (values ('dirigente:comunicazione-formazione-consultazione',1),('dirigente:scenario-manageriale',2)) x(key,pos) join public.learning_units lu on lu.stable_key=x.key join public.learning_unit_versions luv on luv.learning_unit_id=lu.id and luv.version_number=1;
  end if;
end $do$;
